"""Explain live-zero lockrefs and biased RCU reference counts."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1393': ('이용자가 지금 0명인 물건과 사용 종료 표지가 붙은 물건은 다를 수 있습니다. 아직 보관 중인 물건에는 새 이용자를 받을 수 있지만 이미 버린 물건은 되살릴 수 없습니다.', 'get_not_dead가 허용하는 0과 거절하는 음수 상태를 구별합니다.', '경쟁이 없고 객체가 유효하다고 두고 count=-128,0,3을 적으세요. 결과는 유지,1,4이고 반환은 0,1,1입니다. get_not_zero는 0을 거절한다는 차이도 적으세요.', ['lockref_get_not_dead는 참조 수를 하나 늘리되 dead 상태는 거절합니다. 참조는 객체를 계속 쓰겠다는 약속입니다. 이 lockref의 dead 표시는 음수 count이며, 숫자 0과는 다릅니다.', 'CAS 경로는 old.count < 0일 때 실패 0을 반환합니다. CAS는 읽었던 상태가 여전히 같을 때만 새 값을 쓰는 비교·교환입니다. 후보 new의 수를 계산했어도 실패 조건에서 돌아가면 실제 객체에는 저장하지 않습니다.', '0은 음수가 아니므로 CAS가 성공하면 0에서 1로 늘어납니다. 양수 3이면 4로 늘지만 반환값은 똑같이 성공 1입니다. 반환은 새 수가 아니라 새 참조를 얻었는지 알려 주는 값입니다.', 'CAS로 마치지 못하면 spinlock을 얻고 현재 count >= 0인지 확인합니다. 맞으면 증가하고 성공 1, 아니면 변경 없이 실패 0입니다. 이후 잠금을 풀고 돌아갑니다. 두 경로 모두 음수만 거절합니다.', 'get_not_zero는 count <= 0을 거절하지만 get_not_dead는 count < 0만 거절합니다. 두 식에서 등호 하나가 count=0의 결과를 바꿉니다. 이름이 비슷해도 어느 객체 수명 규칙에 필요한지 구별해서 선택해야 합니다.', '0에서 증가할 수 있다고 이미 반납된 메모리를 되살리는 것은 아닙니다. 객체가 아직 존재하고 검사 중 사라지지 않도록 보호된 조건이 필요합니다. 정상 int 범위도 지키고, 성공한 새 참조의 이후 반납 규칙까지 따라야 합니다.'], [('유효한 객체의 count=0에 get_not_dead가 성공하면 어떻게 될까요?', ['get_not_zero처럼 반드시 거절해요', 'count가 1이 되고 성공 1을 반환해요'], '검사는 0 이하가 아니라 0 미만입니다. 0은 허용되므로 증가할 수 있습니다. 다만 객체 수명이 유효하고 정해진 규칙에 맞는 호출이어야 합니다.'), ('이미 free된 주소에 이 함수를 부르면 안전하게 되살릴 수 있을까요?', ['아니요. 아직 유효한 객체여야 해요', '네. 주소만 기억하면 언제나 복구해요'], '함수는 실제 객체의 count와 잠금에 접근합니다. 저장 공간이 이미 반납되었다면 그런 접근 자체가 잘못됩니다. 내부 숫자 조건은 메모리 수명 보호를 대신하지 않습니다.')]), 'os1394': ('번호표를 0부터 붙이면 첫 번째 사람의 번호는 0입니다. rcuref도 실제 참조 수보다 하나 작은 숫자를 저장합니다.', '실제 참조 수와 rcuref 내부 저장값을 두 줄로 나누어 이해합니다.', '실제 참조 수 1,2,3 아래에 내부 값 0,1,2를 적으세요. 마지막 참조를 줄이면 내부 0에서 모든 32비트가 1인 NOREF로 넘어간다고 따로 표시하세요.', ['rcuref는 RCU로 관리하는 객체의 참조 수를 다룹니다. RCU는 읽는 쪽이 남아 있을 수 있는 동안 메모리 반납을 미루는 규칙을 제공하는 기술입니다. 참조 수와 이 규칙을 함께 사용해 객체 수명을 관리합니다.', 'rcuref_init(ref,cnt)는 cnt-1을 내부 refcnt에 저장합니다. 참조 한 개로 시작하면 1-1=0입니다. 그래서 RCUREF_ONEREF 상수도 0입니다. 내부 0을 보고 사용자가 없다고 읽으면 틀립니다.', '일반적인 살아 있는 범위에서는 실제 참조 수가 내부 값+1입니다. 예를 들어 실제 세 개면 내부는 2입니다. 이처럼 일정한 차이를 두어 표현하는 것을 biased count라고 합니다. 이 수업에서는 하나 작게 저장한다고 기억하면 됩니다.', '마지막 참조를 놓을 때 내부 0을 하나 줄입니다. 이 32비트 카운터에서 결과의 비트 표현은 0xffffffff입니다. 0x는 16진수 표시이며 f 하나가 1인 비트 네 개여서 f 여덟 개는 32칸 모두 1입니다. 이 값을 RCUREF_NOREF라고 부릅니다.', '그 비트 표현을 부호 있는 결과로 보면 -1이므로 음수 검사에 걸려 별도 처리인 slowpath로 갑니다. 이 경계를 이용해 흔한 증감 경로와 마지막 처리 경로를 나눕니다. 일반 C의 모든 signed 계산이 이렇게 돌아간다는 뜻은 아니며 커널 원자 연산의 구현 규칙을 보는 것입니다.', 'NOREF가 되었다고 바로 DEAD 저장이나 메모리 반납이 끝난 것은 아닙니다. slowpath가 경쟁 상황을 확인하며 NOREF에서 DEAD로 바꾸기를 시도합니다. 초기화는 객체를 다른 사용자에게 공개하기 전에 마치고, 수명 보호 규칙에 맞게 공개해야 합니다.'], [('참조 한 개로 rcuref를 초기화하면 내부 값은 얼마일까요?', ['1이에요', '0이에요'], 'init은 cnt-1을 저장하므로 1-1=0입니다. 내부 0은 살아 있는 참조 하나를 나타내며 실제 수 0과 구별해야 합니다.'), ('마지막 감소에서 내부 0은 먼저 어떤 표현으로 바뀔까요?', ['NOREF인 0xffffffff로 바뀌어요', '감소 연산 자체가 즉시 DEAD를 저장해요'], '먼저 1을 줄인 비트 표현이 NOREF가 됩니다. 그 뒤 별도 처리에서 DEAD로 바꾸기를 시도하므로 두 단계를 하나로 읽으면 안 됩니다.')]), 'os1395': ('장부 안의 숫자에 1을 더해 실제 수를 알려 주되, 사용 종료 구역의 표시는 0으로 알려 주는 조회를 살펴봅시다.', 'rcuref_read의 구간 판정과 단순 조회의 한계를 이해합니다.', '내부 0이면 read는 1, 내부 2면 3을 적으세요. 내부 0xc0000000부터는 0입니다. 이 조회만으로 새 참조가 생기지 않는다고 표시하세요.', ['rcuref_read는 atomic_read로 내부 카운터를 읽고 unsigned int c에 담습니다. unsigned는 음수 없이 비트 패턴을 숫자로 해석하는 방식입니다. 그래서 높은 비트가 1인 값도 큰 양수로 비교합니다.', 'RCUREF_RELEASED는 0xc0000000입니다. c가 이 값 이상이면 0을 반환합니다. 종료 상태 구역에 있는 값을 일반 참조 수처럼 더해서 알려 주지 않으려는 분기입니다.', '그보다 작으면 c+1을 반환합니다. 살아 있는 일반 범위에서는 하나 작게 저장했던 수를 원래 수로 되돌립니다. 내부 0은 외부 1, 내부 2는 외부 3이 됩니다.', '내부 MAXREF는 0x7fffffff이고 read는 여기에 1을 더한 0x80000000을 반환합니다. 16진수의 각 자리는 0~9 다음 a~f까지 쓰므로 f 다음에는 자리 올림이 일어납니다. 내부 경계값과 외부에 보여 주는 수가 하나 다릅니다.', '0x80000000부터 RELEASED 직전까지는 포화 구역입니다. 포화는 수가 너무 커져 정확한 증감 대신 특별 상태로 유지하는 보호 방식입니다. read 식은 이 구역에도 +1을 적용하지만 그 숫자를 실제 보유자 수의 정밀한 측정으로 믿으면 안 됩니다.', 'read는 상태를 보는 동작이며 새 참조를 얻지 않습니다. 조회 뒤 다른 실행 흐름이 상태를 바꿀 수도 있습니다. 0을 읽었다는 이유만으로 메모리를 반납하지 말고, 마지막 put의 반환과 RCU 수명 규칙에 따라 처리해야 합니다.'], [('내부 값이 MAXREF=0x7fffffff이면 read의 반환은 무엇일까요?', ['그대로 0x7fffffff예요', '1을 더한 0x80000000이에요'], 'MAXREF는 RELEASED보다 작아 c+1 경로를 사용합니다. 내부 저장값을 그대로 보여 주는 함수가 아니라는 점을 확인하세요.'), ('rcuref_read를 호출하면 새 참조도 하나 얻을까요?', ['아니요. 상태를 읽기만 해요', '네. 언제나 get도 함께 수행해요'], '본문에는 atomic_read와 결과 계산만 있습니다. 참조 획득은 get의 역할이며, 조회 결과가 객체 수명 보장을 새로 만들어 주지는 않습니다.')]), 'os1396': ('장부를 바꾸기 전에 계속 비교하는 대신, 먼저 한 칸 올리고 어느 구역에 들어왔는지 살피는 방법입니다. 특별 구역은 별도 담당자가 처리합니다.', 'rcuref_get의 먼저 증가하는 경로와 수명 보호 전제를 이해합니다.', '내부 값 0에서 1을 더하면 1이고 음수가 아니므로 바로 성공합니다. 내부 MAXREF에 1을 더하면 0x80000000이 되어 음수 결과 검사에 걸리고 별도 처리로 간다고 그리세요.', ['rcuref_get은 참조 하나를 얻으려는 함수입니다. 반환 true는 성공, false는 실패입니다. __must_check 표시는 반환을 무시하지 말아야 한다고 도구에 알립니다. 실제 객체 사용은 성공 여부를 확인한 뒤 새 참조의 규칙에 맞춰 이어갑니다.', '빠른 경로는 atomic_add_negative_relaxed(1, &ref->refcnt)를 실행합니다. 내부 값에 먼저 1을 더하고, 새 값을 부호 있는 수로 봤을 때 음수인지 검사합니다. 증가 전에 0인지 반복 비교하는 CAS 방식이 아닙니다.', '새 값이 음수가 아니면 ! 연산으로 조건이 참이 되어 바로 true를 반환합니다. 예를 들어 내부 0은 참조 하나이고, 증가한 내부 1은 참조 둘을 뜻합니다. 내부 수와 실제 수를 구별하세요.', '음수 결과라면 rcuref_get_slowpath로 넘어갑니다. 이 경로가 포화 구역과 종료 구역 등을 처리합니다. 음수 검사에 걸렸다는 사실만으로 곧바로 모든 경우가 실패라고 단정하면 안 됩니다. 최종 반환은 그 함수가 정합니다.', '이 방식은 먼저 증감해도 상태를 구분할 수 있도록 넓은 포화·종료 구역을 둡니다. 흔한 경우의 반복 비교 부담을 줄이려는 설계입니다. 그러나 해제된 주소에 먼저 더해도 안전하다는 뜻은 아닙니다. 호출자는 RCU 등으로 메모리가 유효한 동안 올바르게 포인터를 얻어야 합니다.', 'relaxed는 이 get 자체가 일반 acquire 방식의 데이터 읽기 순서를 제공하지 않는다는 뜻입니다. 성공 결과를 확인한 뒤에만 하는 저장에는 제어 의존 관계가 생기지만, 모든 이후 읽기까지 자동 정렬하는 것과는 다릅니다. 포인터 공개·획득과 객체 수명에 맞는 바깥 규칙을 함께 지켜야 합니다.'], [('빠른 get 경로는 증가 전에 언제나 CAS로 0을 검사할까요?', ['네. 모든 get은 0이 아닌지 CAS를 반복해요', '아니요. 먼저 증가하고 결과를 검사해요'], '원문은 atomic_add_negative_relaxed로 먼저 더합니다. 상태 구역을 이용해 이후 결과를 판정하는 방식이므로 inc-not-zero 반복과 같다고 설명하면 안 됩니다.'), ('rcuref_get 자체가 일반 acquire처럼 모든 보호 데이터 읽기의 순서를 보장할까요?', ['아니요. relaxed이며 바깥의 올바른 포인터 획득 규칙이 필요해요', '네. get만 호출하면 모든 데이터 읽기가 정렬돼요'], '헤더는 메모리 안정성을 호출자가 보장해야 한다고 설명합니다. 성공 확인에 따른 이후 저장의 제어 의존과 일반 acquire 보장은 다릅니다. get만으로 수명·공개 규칙 전체를 대신할 수 없습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_344.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
